	`active` TINYINT(1) NULL DEFAULT 1,
	PRIMARY KEY (`id_ipcatalogexport_email`)
) ENGINE=' . _MYSQL_ENGINE_ . ' DEFAULT CHARSET=utf8;';

$sql[] = 'CREATE TABLE IF NOT EXISTS `' . _DB_PREFIX_ . 'ipcatalogexport_ftp` (
